steps.sampleSolution:
#include <boost/algorithm/string.hpp>
#include <iostream>
#include <string>

int main() {
    std::string s = "  ola  ";
    boost::trim(s);
    boost::to_upper(s);
    std::cout << s << "\n";
    return 0;
}
